  `user_id` bigint(20) unsigned NOT NULL,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_favorites_user_joke` (`user_id`,`joke_id`),
  KEY `idx_favorites_joke` (`joke_id`),
  CONSTRAINT `fk_favorites_joke` FOREIGN KEY (`joke_id`) REFERENCES `jokes` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_favorites_user` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE
