  KEY `idx_game_messages_session_round` (`session_id`,`round_number`,`created_at`),
  CONSTRAINT `fk_game_messages_session` FOREIGN KEY (`session_id`) REFERENCES `game_sessions` (`id`) ON DELETE CASCADE
