DROP TABLE IF EXISTS `game_sessions`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `game_sessions` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `user_id` bigint(20) unsigned NOT NULL,
  `game_type` enum('joke_battle','word_chain','punchline_guess') NOT NULL,
  `status` enum('in_progress','completed','abandoned','error') NOT NULL DEFAULT 'in_progress',
  `player_score` decimal(7,2) NOT NULL DEFAULT 0.00,
  `ai_score` decimal(7,2) NOT NULL DEFAULT 0.00,
  `result` enum('win','loss','draw','pending') NOT NULL DEFAULT 'pending',
  `started_at` datetime NOT NULL DEFAULT current_timestamp(),
  `ended_at` datetime DEFAULT NULL,
  `metadata` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`metadata`)),
  PRIMARY KEY (`id`),
  KEY `idx_game_sessions_user_type` (`user_id`,`game_type`,`started_at`),
  KEY `idx_game_sessions_status` (`status`,`started_at`),
  CONSTRAINT `fk_game_sessions_user` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE
