  PRIMARY KEY (`joke_id`,`tag_id`),
  KEY `idx_joke_tags_tag` (`tag_id`),
  CONSTRAINT `fk_joke_tags_joke` FOREIGN KEY (`joke_id`) REFERENCES `jokes` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_joke_tags_tag` FOREIGN KEY (`tag_id`) REFERENCES `tags` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
