DROP TABLE IF EXISTS `jokes`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `jokes` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `user_id` bigint(20) unsigned NOT NULL,
  `category_id` bigint(20) unsigned NOT NULL,
  `title` varchar(180) NOT NULL,
  `content` text NOT NULL,
  `country_code` char(2) DEFAULT NULL,
  `language_code` varchar(10) NOT NULL DEFAULT 'vi',
  `image_path` varchar(500) DEFAULT NULL,
  `status` enum('pending','published','rejected','hidden','deleted') NOT NULL DEFAULT 'pending',
  `moderation_note` varchar(1000) DEFAULT NULL,
  `moderated_by` bigint(20) unsigned DEFAULT NULL,
  `moderated_at` datetime DEFAULT NULL,
  `view_count` bigint(20) unsigned NOT NULL DEFAULT 0,
  `published_at` datetime DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `updated_at` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `fk_jokes_moderator` (`moderated_by`),
  KEY `idx_jokes_status_created` (`status`,`created_at`),
  KEY `idx_jokes_category_status` (`category_id`,`status`),
  KEY `idx_jokes_author_created` (`user_id`,`created_at`),
  KEY `idx_jokes_country_language` (`country_code`,`language_code`),
  FULLTEXT KEY `ft_jokes_title_content` (`title`,`content`),
  CONSTRAINT `fk_jokes_author` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`),
  CONSTRAINT `fk_jokes_category` FOREIGN KEY (`category_id`) REFERENCES `categories` (`id`),
  CONSTRAINT `fk_jokes_moderator` FOREIGN KEY (`moderated_by`) REFERENCES `users` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=94 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
